const encoder = new TextEncoder();
const sourcePackChecker = createRequire(import.meta.url)(
  "../../../scripts/check-stage09p-m1-source-pack.mjs",
);
const compareUtf8 = (left: string, right: string): number => {
  const leftBytes = encoder.encode(left);
  const rightBytes = encoder.encode(right);
  for (let index = 0; index < Math.min(leftBytes.length, rightBytes.length); index += 1) {
    const difference = leftBytes[index]! - rightBytes[index]!;
    if (difference !== 0) return difference;
  }
  return leftBytes.length - rightBytes.length;
};

const canonicalJson = (value: unknown): string => {
  if (value === null) return "null";
  if (typeof value === "string" || typeof value === "number") return JSON.stringify(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (Array.isArray(value)) return "[" + value.map(canonicalJson).join(",") + "]";
  assert.equal(typeof value, "object");
  const record = value as Readonly<Record<string, unknown>>;
  return (
    "{" +
    Object.keys(record)
      .sort(compareUtf8)
      .map((key) => JSON.stringify(key) + ":" + canonicalJson(record[key]))
      .join(",") +
    "}"
  );
};

const sha256 = (bytes: Uint8Array): string =>
  "sha256:" + createHash("sha256").update(bytes).digest("hex");

const framedDigest = (tag: string, material: unknown): string => {
  const tagBytes = encoder.encode(tag);
  const textBytes = encoder.encode(canonicalJson(material));
  const framed = new Uint8Array(tagBytes.length + 1 + textBytes.length);
  framed.set(tagBytes);
  framed[tagBytes.length] = 0;
  framed.set(textBytes, tagBytes.length + 1);
  return sha256(framed);
};

const deepFreeze = <T>(value: T): T => {
  if (value === null || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor !== undefined && "value" in descriptor) deepFreeze(descriptor.value);
  }
  return Object.freeze(value);
};

const clone = <T>(value: T): T => structuredClone(value);

