const releaseDigest = (release: GovernanceRelease): string => {
  const material = {
    ...(release.$schema === undefined ? {} : { $schema: release.$schema }),
    schemaVersion: release.schemaVersion,
    releaseId: release.releaseId,
    releaseRevision: release.releaseRevision,
    envelopes: release.envelopes,
  };
  return sha256(encoder.encode(canonicalJson(material)));
};

const reviewMaterial = (review: MappingReview): unknown => ({
  mappingId: review.mappingId,
  reviewRevision: review.reviewRevision,
  sourceBindingId: review.sourceBindingId,
  targetBindingId: review.targetBindingId,
  source: review.source,
  target: review.target,
  required: review.required,
  reviewStatus: review.reviewStatus,
  effectiveFrom: review.effectiveFrom,
  effectiveUntil: review.effectiveUntil,
});

const normalizedMapping = (mapping: HouseholdDishSafetyInput["dish"]["exposures"][number]["mapping"]): unknown =>
  mapping.status === "mapped"
    ? { status: "mapped", mappingIds: [...mapping.mappingIds].sort(compareUtf8) }
    : mapping.status === "ambiguous"
      ? {
          status: "ambiguous",
          candidateMappingIds: [...mapping.candidateMappingIds].sort(compareUtf8),
        }
      : { status: "unknown" };

const dishMaterial = (input: HouseholdDishSafetyInput["dish"]): unknown => ({
  dishId: input.dishId,
  dishRevision: input.dishRevision,
  exposures: [...input.exposures]
    .sort((left, right) => compareUtf8(left.exposureId, right.exposureId))
    .map((exposure) => ({
      exposureId: exposure.exposureId,
      kind: exposure.kind,
      mapping: normalizedMapping(exposure.mapping),
    })),
});

const dishDigest = (dish: HouseholdDishSafetyInput["dish"]): string =>
  framedDigest("stage09p-m1-household-safety-dish-v1", dishMaterial(dish));

const requestMaterial = (input: HouseholdDishSafetyInput): unknown => ({
  schemaVersion: input.schemaVersion,
  asOf: input.asOf,
  household: {
    country: input.household.country,
    foodRuleRegion: input.household.foodRuleRegion,
  },
  expectedSourcePack: {
    packId: input.expectedSourcePack.packId,
    packRevision: input.expectedSourcePack.packRevision,
    contentDigest: input.expectedSourcePack.contentDigest,
  },
  householdProfiles: [...input.householdProfiles]
    .sort((left, right) => compareUtf8(left.profileId, right.profileId))
    .map((profile) => ({
      profileId: profile.profileId,
      status: profile.status,
      constraints: [...profile.constraints]
        .sort((left, right) => compareUtf8(left.constraintId, right.constraintId))
        .map((constraint) => ({
          constraintId: constraint.constraintId,
          kind: constraint.kind,
          basis: constraint.basis,
          mapping: normalizedMapping(constraint.mapping),
        })),
    })),
  mealParticipantProfileIds: [...input.mealParticipantProfileIds].sort(compareUtf8),
  guestParticipants: [...input.guestParticipants]
    .sort((left, right) => compareUtf8(left.guestId, right.guestId))
    .map((guest) => ({
      guestId: guest.guestId,
      constraints: [...guest.constraints]
        .sort((left, right) => compareUtf8(left.constraintId, right.constraintId))
        .map((constraint) => ({
          constraintId: constraint.constraintId,
          kind: constraint.kind,
          basis: constraint.basis,
          mapping: normalizedMapping(constraint.mapping),
        })),
    })),
  dish: {
    dishId: input.dish.dishId,
    dishRevision: input.dish.dishRevision,
    contentDigest: input.dish.contentDigest,
    exposures: [...input.dish.exposures]
      .sort((left, right) => compareUtf8(left.exposureId, right.exposureId))
      .map((exposure) => ({
        exposureId: exposure.exposureId,
        kind: exposure.kind,
        mapping: normalizedMapping(exposure.mapping),
      })),
  },
});

const requestDigest = (input: HouseholdDishSafetyInput): string =>
  framedDigest("stage09p-m1-household-safety-request-v2", requestMaterial(input));

const graphMaterial = (graph: InternalSyntheticGovernedGraph): unknown => ({
  schemaVersion: graph.schemaVersion,
  packId: graph.packId,
  packRevision: graph.packRevision,
  country: graph.country,
  foodRuleRegion: graph.foodRuleRegion,
  ruleLanguage: graph.ruleLanguage,
  syntheticSourceUsageStatus: graph.syntheticSourceUsageStatus,
  releaseBindings: [...graph.releaseBindings].sort((left, right) =>
    compareUtf8(left.bindingId, right.bindingId),
  ),
  sourceVersionWindows: [...graph.sourceVersionWindows].sort((left, right) => {
    const binding = compareUtf8(left.bindingId, right.bindingId);
    if (binding !== 0) return binding;
    const from = compareUtf8(left.effectiveFrom, right.effectiveFrom);
    if (from !== 0) return from;
    if (left.effectiveUntil === right.effectiveUntil) {
      return compareUtf8(canonicalJson(left), canonicalJson(right));
    }
    if (left.effectiveUntil === null) return -1;
    if (right.effectiveUntil === null) return 1;
    return compareUtf8(left.effectiveUntil, right.effectiveUntil);
  }),
  mappingReviews: [...graph.mappingReviews].sort((left, right) => {
    const mapping = compareUtf8(left.mappingId, right.mappingId);
    if (mapping !== 0) return mapping;
    const revision = left.reviewRevision - right.reviewRevision;
    return revision !== 0
      ? revision
      : compareUtf8(canonicalJson(left), canonicalJson(right));
  }),
  catalog: graph.catalog,
  endpointFacts: [...graph.endpointFacts].sort((left, right) => {
    const dataset = compareUtf8(left.reference.datasetId, right.reference.datasetId);
    if (dataset !== 0) return dataset;
    const entity = compareUtf8(left.reference.entityId, right.reference.entityId);
    if (entity !== 0) return entity;
    const revision = left.reference.entityRevision - right.reference.entityRevision;
    return revision !== 0
      ? revision
      : compareUtf8(left.syntheticDisposition, right.syntheticDisposition);
  }),
});

const graphDigest = (graph: InternalSyntheticGovernedGraph): string =>
  framedDigest("stage09p-m1-internal-synthetic-pipeline-v2", graphMaterial(graph));

