const makeRelease = (
  releaseId: string,
  envelope: GovernanceEnvelope,
): GovernanceRelease => {
  const release: GovernanceRelease = {
    schemaVersion: 1,
    releaseId,
    releaseRevision: 1,
    contentDigest: "sha256:" + "0".repeat(64),
    envelopes: [envelope],
  };
  return { ...release, contentDigest: releaseDigest(release) };
};

