interface GuestMatrixSelectorGolden {
  readonly location: "dish_exposure" | "personal_hard" | "soft";
  readonly subject: Readonly<{ readonly kind: "household_profile" | "guest"; readonly id: string }> | null;
  readonly constraintId: string | null;
  readonly selection: HouseholdDishSafetyInput["dish"]["exposures"][number]["mapping"];
  readonly coverageUnitKey: Readonly<Record<string, unknown>> | null;
  readonly exposureId: string | null;
}

interface GuestMatrixGolden {
  readonly rowId: string;
  readonly label: string;
  readonly oracleId: string;
  readonly requestDigest: string;
  readonly sourcePackDigest: string;
  readonly evaluationDigest: string;
  readonly selectorOrigins: readonly GuestMatrixSelectorGolden[];
  readonly mappingLookups: readonly Readonly<{ readonly mappingId: string; readonly count: number }>[];
  readonly endpointFacts: readonly Readonly<{
    readonly reference: Readonly<{ readonly datasetId: string; readonly entityId: string; readonly entityRevision: number }>;
    readonly factHitCount: number;
    readonly disposition: string | null;
  }>[];
  readonly bindingStates: readonly Readonly<{
    readonly mappingId: string;
    readonly endpoint: "source" | "target";
    readonly structuralCount: number;
    readonly currentCount: number;
    readonly selectedBindingId: string | null;
  }>[];
  readonly reviewCounts: readonly Readonly<{ readonly mappingId: string; readonly count: number }>[];
  readonly privateCoverage: readonly Readonly<{
    readonly unit: Readonly<Record<string, unknown>>;
    readonly clearSupported: boolean;
    readonly ownFailureCodes: readonly string[];
    readonly knownHardAccounted: boolean;
    readonly resolved: boolean;
  }>[];
}

const GUEST_FAILURE_CODES = new Set([
  "source_fact_unknown",
  "source_fact_candidate_clear",
  "mapping_unknown",
  "mapping_ambiguous",
  "mapping_invalid",
  "mapping_withdrawn",
  "mapping_version_mismatch",
  "mapping_unapproved",
  "mapping_required_false",
  "mapping_target_kind_mismatch",
  "mapping_source_unbound",
  "mapping_source_multiple_bindings",
  "mapping_target_unbound",
  "mapping_target_multiple_bindings",
  "mapping_endpoint_not_current",
  "mapping_review_missing",
  "mapping_review_mismatch",
  "mapping_review_not_current",
] as const);

const GUEST_KNOWN_HARD_CODES = new Set([
  "household_allergy_match",
  "guest_allergy_match",
  "personal_religious_match",
  "personal_ethical_match",
  "personal_strict_avoid_match",
] as const);

const guestReferenceText = (reference: {
  readonly datasetId: string;
  readonly entityId: string;
  readonly entityRevision: number;
}): string =>
  reference.datasetId + "\u0000" + reference.entityId + "\u0000" + reference.entityRevision;

const deriveGuestSelectorOrigins = (
  input: HouseholdDishSafetyInput,
): readonly GuestMatrixSelectorGolden[] => {
  const selectors: GuestMatrixSelectorGolden[] = [];
  for (const exposure of input.dish.exposures) {
    selectors.push({
      location: "dish_exposure",
      subject: null,
      constraintId: null,
      selection: exposure.mapping,
      coverageUnitKey: { kind: "dish_exposure", exposureId: exposure.exposureId },
      exposureId: exposure.exposureId,
    });
  }
  const participants = new Set(input.mealParticipantProfileIds);
  for (const profile of input.householdProfiles) {
    if (profile.status !== "active" || !participants.has(profile.profileId)) continue;
    const subject = { kind: "household_profile" as const, id: profile.profileId };
    for (const constraint of profile.constraints) {
      if (constraint.kind === "allergy") continue;
      const hard =
        constraint.kind === "religious" ||
        constraint.kind === "ethical" ||
        constraint.kind === "explicit_strict_avoid";
      selectors.push({
        location: hard ? "personal_hard" : "soft",
        subject,
        constraintId: constraint.constraintId,
        selection: constraint.mapping,
        coverageUnitKey: hard
          ? { kind: "personal_hard", subject, constraintId: constraint.constraintId }
          : null,
        exposureId: null,
      });
    }
  }
  for (const guest of input.guestParticipants) {
    const subject = { kind: "guest" as const, id: guest.guestId };
    for (const constraint of guest.constraints) {
      if (constraint.kind === "allergy") continue;
      const hard =
        constraint.kind === "religious" ||
        constraint.kind === "ethical" ||
        constraint.kind === "explicit_strict_avoid";
      selectors.push({
        location: hard ? "personal_hard" : "soft",
        subject,
        constraintId: constraint.constraintId,
        selection: constraint.mapping,
        coverageUnitKey: hard
          ? { kind: "personal_hard", subject, constraintId: constraint.constraintId }
          : null,
        exposureId: null,
      });
    }
  }
  return selectors;
};

const deriveGuestBindingState = (
  graph: InternalSyntheticGovernedGraph,
  reference: { readonly datasetId: string; readonly entityId: string; readonly entityRevision: number },
): Readonly<{
  structuralCount: number;
  currentCount: number;
  selectedBindingId: string | null;
}> => {
  const structural = graph.releaseBindings.filter((binding) => {
    const release = graph.catalog.releases.find(
      (candidate) =>
        candidate.releaseId === binding.releaseId &&
        candidate.releaseRevision === binding.releaseRevision &&
        candidate.contentDigest === binding.releaseDigest,
    );
    return (
      binding.datasetId === reference.datasetId &&
      release?.envelopes.some(
        (envelope) =>
          envelope.datasetId === reference.datasetId &&
          envelope.entityId === reference.entityId &&
          envelope.entityRevision === reference.entityRevision &&
          envelope.datasetKind === binding.datasetKind,
      ) === true
    );
  });
  const current = structural.filter(
    (binding) =>
      graph.sourceVersionWindows.filter(
        (window) =>
          window.bindingId === binding.bindingId &&
          window.effectiveFrom <= "2026-08-29T00:00:00.000Z" &&
          (window.effectiveUntil === null ||
            "2026-08-29T00:00:00.000Z" < window.effectiveUntil),
      ).length === 1,
  );
  return {
    structuralCount: structural.length,
    currentCount: current.length,
    selectedBindingId: current.length === 1 ? current[0]!.bindingId : null,
  };
};

const deriveGuestPrivateCoverage = (
  input: HouseholdDishSafetyInput,
  graph: InternalSyntheticGovernedGraph,
  expected: HouseholdDishSafetyEvaluation,
): GuestMatrixGolden["privateCoverage"] => {
  const selectors = deriveGuestSelectorOrigins(input);
  const reasons = [
    ...expected.tableReasons,
    ...expected.subjects.flatMap((subject) => subject.reasons),
  ];
  const matches = reasons.filter((reason) => GUEST_KNOWN_HARD_CODES.has(reason.code as never));
  const rows: Array<GuestMatrixGolden["privateCoverage"][number]> = [];
  for (const selector of selectors) {
    if (selector.coverageUnitKey === null) continue;
    const selectorSubject = selector.subject;
    if (selector.location !== "dish_exposure" && selectorSubject === null) {
      throw new Error("guest selector subject missing");
    }
    const ownFailureCodes = reasons
      .filter((reason) => {
        if (!GUEST_FAILURE_CODES.has(reason.code as never)) return false;
        if (selector.location === "dish_exposure") {
          return reason.exposureId === selector.exposureId;
        }
        return (
          reason.subject?.kind === selectorSubject!.kind &&
          reason.subject.id === selectorSubject!.id &&
          reason.constraintId === selector.constraintId
        );
      })
      .map((reason) => reason.code)
      .sort(compareUtf8);
    const knownHardAccounted = matches.some((reason) =>
      selector.location === "dish_exposure"
        ? reason.exposureId === selector.exposureId
        : reason.subject?.kind === selectorSubject!.kind &&
          reason.subject.id === selectorSubject!.id &&
          reason.constraintId === selector.constraintId,
    );
    let clearSupported = false;
    if (selector.selection.status === "mapped") {
      for (const mappingId of selector.selection.mappingIds) {
        const mapping = graph.catalog.hardMappings.find(
          (candidate) => candidate.mappingId === mappingId,
        );
        if (mapping === undefined) continue;
        const failed = reasons.some(
          (reason) =>
            GUEST_FAILURE_CODES.has(reason.code as never) &&
            reason.mappingId === mappingId &&
            (selector.location === "dish_exposure"
              ? reason.exposureId === selector.exposureId
              : reason.subject?.kind === selectorSubject!.kind &&
                reason.subject.id === selectorSubject!.id &&
                reason.constraintId === selector.constraintId),
        );
        const sourceDisposition = graph.endpointFacts.find(
          (fact) => guestReferenceText(fact.reference) === guestReferenceText(mapping.source),
        )?.syntheticDisposition;
        const targetDisposition = graph.endpointFacts.find(
          (fact) => guestReferenceText(fact.reference) === guestReferenceText(mapping.target),
        )?.syntheticDisposition;
        if (
          !failed &&
          sourceDisposition === "REVIEWED_CLEAR" &&
          targetDisposition === "REVIEWED_CLEAR"
        ) {
          clearSupported = true;
        }
      }
    }
    rows.push({
      unit: selector.coverageUnitKey,
      clearSupported,
      ownFailureCodes,
      knownHardAccounted,
      resolved: clearSupported || ownFailureCodes.length > 0 || knownHardAccounted,
    });
  }
  return rows;
};

const assertGuestMatrixWitness = (
  input: HouseholdDishSafetyInput,
  graph: InternalSyntheticGovernedGraph,
  expected: HouseholdDishSafetyEvaluation,
  golden: GuestMatrixGolden,
): void => {
  const inputBefore = canonicalJson(input);
  const graphBefore = canonicalJson(graph);
  assertRecursivelyFrozen(input);
  assertRecursivelyFrozen(graph);
  assertRecursivelyFrozen(expected);
  assertRecursivelyFrozen(golden);
  assert.equal(
    input.mealParticipantProfileIds.length > 0 || input.guestParticipants.length > 0,
    true,
  );
  assert.equal(requestDigest(input), golden.requestDigest);
  assert.equal(graphDigest(graph), golden.sourcePackDigest);
  assert.equal(expected.requestDigest, golden.requestDigest);
  assert.equal(expected.sourcePackDigest, golden.sourcePackDigest);
  assert.equal(expected.evaluationDigest, golden.evaluationDigest);
  assert.deepStrictEqual(Object.keys(expected), [
    "evaluationDigest",
    "inputIssue",
    "requestDigest",
    "schemaVersion",
    "sourcePackDigest",
    "subjects",
    "tableReasons",
    "tableStatus",
  ]);
  for (const reason of [
    ...expected.tableReasons,
    ...expected.subjects.flatMap((subject) => subject.reasons),
  ]) {
    assert.deepStrictEqual(Object.keys(reason), [
      "code",
      "constraintId",
      "constraintMappingId",
      "exposureId",
      "exposureKind",
      "exposureMappingId",
      "mappingEndpoint",
      "mappingId",
      "scope",
      "subject",
    ]);
  }
  const decodedCatalog = decodeGovernanceCatalog(graph.catalog);
  assert.equal(decodedCatalog.ok, true);
  if (!decodedCatalog.ok) throw new Error("unreachable guest catalog");
  assert.deepStrictEqual(decodedCatalog.value, graph.catalog);
  assert.deepStrictEqual(deriveGuestSelectorOrigins(input), golden.selectorOrigins);
  const requestedMappingIds = [
    ...new Set(
      deriveGuestSelectorOrigins(input).flatMap((selector) =>
        selector.selection.status === "mapped" ? selector.selection.mappingIds : [],
      ),
    ),
  ].sort(compareUtf8);
  assert.deepStrictEqual(
    requestedMappingIds.map((mappingId) => ({
      mappingId,
      count: graph.catalog.hardMappings.filter(
        (mapping) => mapping.mappingId === mappingId,
      ).length,
    })),
    golden.mappingLookups,
  );
  const references = new Map<
    string,
    { readonly datasetId: string; readonly entityId: string; readonly entityRevision: number }
  >();
  for (const mapping of graph.catalog.hardMappings) {
    references.set(guestReferenceText(mapping.source), mapping.source);
    references.set(guestReferenceText(mapping.target), mapping.target);
  }
  const endpointFacts = [...references.values()]
    .sort((left, right) => compareUtf8(guestReferenceText(left), guestReferenceText(right)))
    .map((reference) => {
      const hits = graph.endpointFacts.filter(
        (fact) => guestReferenceText(fact.reference) === guestReferenceText(reference),
      );
      return {
        reference,
        factHitCount: hits.length,
        disposition: hits.length === 1 ? hits[0]!.syntheticDisposition : null,
      };
    });
  assert.deepStrictEqual(endpointFacts, golden.endpointFacts);
  assert.equal(endpointFacts.every(({ factHitCount }) => factHitCount === 1), true);
  assert.equal(graph.endpointFacts.length, references.size);
  const authorityTuples = graph.releaseBindings.map((binding) =>
    canonicalJson({
      datasetId: binding.datasetId,
      datasetKind: binding.datasetKind,
      releaseId: binding.releaseId,
      releaseRevision: binding.releaseRevision,
      sourceReferenceId: binding.sourceReferenceId,
      sourceReferenceRevision: binding.sourceReferenceRevision,
      sourceVersion: binding.sourceVersion,
    }),
  );
  assert.equal(new Set(authorityTuples).size, authorityTuples.length);
  assert.equal(
    graph.releaseBindings.every(
      (binding) =>
        graph.sourceVersionWindows.filter(
          (window) => window.bindingId === binding.bindingId,
        ).length === 1,
    ),
    true,
  );
  assert.deepStrictEqual(
    graph.catalog.hardMappings.flatMap((mapping) => [
      { mappingId: mapping.mappingId, endpoint: "source", ...deriveGuestBindingState(graph, mapping.source) },
      { mappingId: mapping.mappingId, endpoint: "target", ...deriveGuestBindingState(graph, mapping.target) },
    ]),
    golden.bindingStates,
  );
  assert.deepStrictEqual(
    graph.catalog.hardMappings.map((mapping) => ({
      mappingId: mapping.mappingId,
      count: graph.mappingReviews.filter((review) => review.mappingId === mapping.mappingId)
        .length,
    })),
    golden.reviewCounts,
  );
  assert.deepStrictEqual(deriveGuestPrivateCoverage(input, graph, expected), golden.privateCoverage);
  assert.equal(
    golden.privateCoverage.every(
      (entry) =>
        entry.resolved ===
        (entry.clearSupported || entry.ownFailureCodes.length > 0 || entry.knownHardAccounted),
    ),
    true,
  );
  assert.equal(canonicalJson(input), inputBefore);
  assert.equal(canonicalJson(graph), graphBefore);
};

