type ManifestAnalyzedResult = ReturnType<typeof __testOnlyAnalyzeSyntheticHouseholdSafety>;
const projectManifestAnalyzedSuccess = (actual: ManifestAnalyzedResult): unknown => {
  if (!actual.ok) return actual;
  const state = actual.state;
  const stringKeys = Reflect.ownKeys(state).filter((key): key is string => typeof key === "string");
  assert.deepStrictEqual(stringKeys, ["schemaVersion","subjects","tableKnownHardReasons","tableUncertaintyReasons","subjectKnownHardReasons","subjectUncertaintyReasons","softReasons","requestDigest","sourcePackDigest"]);
  const symbolKeys = Reflect.ownKeys(state).filter((key): key is symbol => typeof key === "symbol");
  assert.equal(symbolKeys.length, 1);
  const symbolKey = symbolKeys[0]!;
  const descriptor = Object.getOwnPropertyDescriptor(state, symbolKey);
  assert.notEqual(descriptor, undefined);
  assertRecursivelyFrozen(state);
  return deepFreeze({ ok: true, stringState: { schemaVersion: state.schemaVersion, subjects: state.subjects, tableKnownHardReasons: state.tableKnownHardReasons, tableUncertaintyReasons: state.tableUncertaintyReasons, subjectKnownHardReasons: state.subjectKnownHardReasons, subjectUncertaintyReasons: state.subjectUncertaintyReasons, softReasons: state.softReasons, requestDigest: state.requestDigest, sourcePackDigest: state.sourcePackDigest }, brandDescriptor: { symbolOwnKeyCount: 1, description: symbolKey.description, value: descriptor!.value, enumerable: descriptor!.enumerable, writable: descriptor!.writable, configurable: descriptor!.configurable }, recursivelyFrozen: true });
};
const captureManifestTypeError = (invoke: () => unknown): Readonly<{ readonly name: "TypeError"; readonly message: string }> => {
  let caught: unknown;
  try { invoke(); } catch (error) { caught = error; }
  assert.equal(caught instanceof TypeError, true);
  if (!(caught instanceof TypeError)) throw new Error("expected TypeError");
  assert.equal(caught.constructor, TypeError);
  assert.equal(caught.name, "TypeError");
  return deepFreeze({ name: "TypeError" as const, message: caught.message });
};
