test("v10 compact digest vectors and independent framing", () => {
  assert.equal(
    dishDigest({
      dishId: "dish:a",
      dishRevision: 1,
      contentDigest: "sha256:" + "0".repeat(64),
      exposures: [
        {
          exposureId: "exposure:a",
          kind: "primary",
          mapping: { status: "unknown" },
        },
      ],
    }),
    "sha256:fac0d2447d348e24f25e25be87762c9d49c3a3ac62a370cbb3b5a8d7854f815b",
  );
  assert.equal(
    framedDigest(
      "stage09p-m1-internal-synthetic-pipeline-v2",
      {
        schemaVersion: 2,
        packId: "pack:s",
        packRevision: 1,
        country: "CN",
        foodRuleRegion: "CN",
        ruleLanguage: "zh-CN",
        syntheticSourceUsageStatus: "approved",
        releaseBindings: [],
        sourceVersionWindows: [],
        mappingReviews: [],
        catalog: { schemaVersion: 1, releases: [], hardMappings: [] },
        endpointFacts: [],
      },
    ),
    "sha256:b52c4cb1e87802ce0147d005d16fd604caf611162e39528aaf4096d2ec7e4ab7",
  );
  assert.equal(
    framedDigest("stage09p-m1-household-safety-official-pack-v2", {
      schemaVersion: 2,
      packId: "pack:o",
      packRevision: 1,
      lifecycleStatus: "draft",
      country: "CN",
      foodRuleRegion: "CN",
      ruleLanguage: "zh-CN",
      releaseBindings: [],
      sourceVersionWindows: [],
      mappingReviews: [],
      catalog: { schemaVersion: 1, releases: [], hardMappings: [] },
    }),
    "sha256:e242c7d20394b3ffc6b590799912d6b17ed23c512d1ec506790c993388f70222",
  );
  assert.equal(
    framedDigest("stage09p-m1-internal-synthetic-kernel-request-v1", {
      schemaVersion: 1,
      subjects: [{ kind: "household_profile", id: "profile:a" }],
    }),
    "sha256:5ad121e928e9193deb1da169ef60a4217a36d2dc71a3c8a70b76946ed74a1882",
  );
  assert.equal(
    framedDigest("stage09p-m1-internal-synthetic-kernel-source-v1", {
      schemaVersion: 1,
      tableKnownHardReasons: [],
      tableUncertaintyReasons: [],
      subjectKnownHardReasons: [],
      subjectUncertaintyReasons: [],
      softReasons: [],
    }),
    "sha256:644048bbc82b11b09e363b69cf796b75dd7d9b5a76146bb7cc5f26d4edfcb83e",
  );
  const tags = [
    "stage09p-m1-household-safety-dish-v1",
    "stage09p-m1-household-safety-request-v2",
    "stage09p-m1-household-safety-official-pack-v2",
    "stage09p-m1-household-safety-mapping-review-v1",
    "stage09p-m1-internal-synthetic-pipeline-v2",
    "stage09p-m1-internal-synthetic-kernel-request-v1",
    "stage09p-m1-internal-synthetic-kernel-source-v1",
    "stage09p-m1-household-safety-evaluation-v2",
  ];
  assert.equal(new Set(tags).size, 8);
  assert(tags.every((tag) => /^[\x20-\x7e]+$/.test(tag) && !tag.includes("\u0000")));
});

test("real draft object and raw routes retain verified official pack digest", () => {
  const decoded = decodeHouseholdSafetySourcePack(realDraftPack);
  assert.equal(decoded.ok, true);
  assert.deepStrictEqual(
    evaluateHouseholdDishSafety(PUBLIC_INPUT, realDraftPack),
    publicDraftExpected,
  );
  assert.deepStrictEqual(
    evaluateHouseholdDishSafety(
      JSON.stringify(PUBLIC_INPUT),
      JSON.stringify(realDraftPack),
    ),
    publicDraftExpected,
  );
});

test("PIPE green uses production input, strict synthetic graph, review and facts", () => {
  assert.equal(decodeGovernanceCatalog(PIPE_FIXTURE.graph.catalog).ok, true);
  assert.deepStrictEqual(
    analyzeHouseholdSafetySourcePackStructure({
      schemaVersion: 2,
      packId: PIPE_FIXTURE.graph.packId,
      packRevision: PIPE_FIXTURE.graph.packRevision,
      contentDigest: graphDigest(PIPE_FIXTURE.graph),
      lifecycleStatus: "active",
      country: "CN",
      foodRuleRegion: "CN",
      ruleLanguage: "zh-CN",
      releaseBindings: PIPE_FIXTURE.graph.releaseBindings,
      sourceVersionWindows: PIPE_FIXTURE.graph.sourceVersionWindows,
      mappingReviews: PIPE_FIXTURE.graph.mappingReviews,
      catalog: PIPE_FIXTURE.graph.catalog,
    }),
    [],
  );
  assert.deepStrictEqual(
    __testOnlyEvaluateGovernedHouseholdSafetyScenario(
      PIPE_FIXTURE.input,
      PIPE_FIXTURE.graph,
    ),
    PIPE_FIXTURE.expected,
  );
});

test("analyzed seam creates the private brand and KERNEL rejects lookalikes", () => {
  const analyzed = __testOnlyAnalyzeSyntheticHouseholdSafety(ANALYZED_SCENARIO);
  assert.equal(analyzed.ok, true);
  if (!analyzed.ok) throw new Error("unreachable");
  assert.equal(Reflect.ownKeys(analyzed.state).filter((key) => typeof key === "symbol").length, 1);
  assert.deepStrictEqual(
    __testOnlyEvaluateAnalyzedHouseholdSafety(analyzed.state),
    ANALYZED_EXPECTED,
  );
  assert.throws(
    () =>
      Reflect.apply(__testOnlyEvaluateAnalyzedHouseholdSafety, undefined, [
        { ...ANALYZED_SCENARIO, requestDigest: "sha256:" + "0".repeat(64), sourcePackDigest: "sha256:" + "0".repeat(64) },
      ]),
    new TypeError("Invalid internal analyzed household safety state"),
  );
});

test("strict graph boundary rejects precomputed or authority override keys", () => {
  for (const key of [
    "bindingCandidates",
    "reduction",
    "m0State",
    "factState",
    "selectorLocation",
    "tableKnownHardReasons",
    "internalGovernedAnalyzerBrand",
  ]) {
    const graph = { ...clone(PIPE_FIXTURE.graph), [key]: true };
    assert.throws(
      () =>
        __testOnlyEvaluateGovernedHouseholdSafetyScenario(
          PIPE_FIXTURE.input,
          graph,
        ),
      new TypeError("Invalid internal governed household safety graph"),
    );
  }
});

test("empty exposure input terminates before graph boundary", () => {
  const input = clone(PIPE_FIXTURE.input);
  Object.assign(input.dish, {
    exposures: [],
    contentDigest:
      "sha256:26450be5aafb9650d8679b3e94372e34e6f4b91f8f768d3a4dd989bcd5ff20b5",
  });
  const result = __testOnlyEvaluateGovernedHouseholdSafetyScenario(
    input,
    Object.defineProperty({}, "schemaVersion", {
      enumerable: true,
      get: () => {
        throw new Error("graph read");
      },
    }),
  );
  assert.deepStrictEqual(result.inputIssue, {
    code: "EMPTY_DISH_EXPOSURES",
    path: "/dish/exposures",
  });
  assert.equal(result.requestDigest, null);
  assert.equal(result.sourcePackDigest, null);
});

test("277-case manifest expands to exact 717 routes and histogram", () => {
  assert.equal(CONTRACT_CASES.length, 277);
  const ids = new Set(CONTRACT_CASES.map((entry) => entry.id));
  assert.equal(ids.size, 277);
  const routes = CONTRACT_CASES.flatMap((entry) => entry.route);
  assert.equal(routes.length, 717);
  const histogram = Object.fromEntries(
    [
      "PNULL",
      "PRAW",
      "POBJ",
      "PIPE",
      "ANALYZE",
      "KERNEL",
      "CLASSIFIER",
      "DECODER",
      "SCLASS",
      "SCHECK",
      "STATIC",
      "DATA",
    ].map((route) => [route, routes.filter((value) => value === route).length]),
  );
  assert.deepStrictEqual(histogram, {
    PNULL: 4,
    PRAW: 113,
    POBJ: 58,
    PIPE: 326,
    ANALYZE: 30,
    KERNEL: 115,
    CLASSIFIER: 10,
    DECODER: 1,
    SCLASS: 14,
    SCHECK: 7,
    STATIC: 20,
    DATA: 19,
  });
  assert.equal(CONTRACT_CASES.flatMap((entry) => entry.invocations).length, 698);
});


