test("CUR-01", () => {
  assertCONTRACT_CUR_01Constructible();
  assertRecursivelyFrozen(S0_CUR_01_NEGATIVE_INPUT);
  assertRecursivelyFrozen(S0_CUR_01_NEGATIVE_GRAPH);
  assertRecursivelyFrozen(S0_CUR_01_NEGATIVE_ORACLE);
  assertRecursivelyFrozen(MANIFEST_CUR_01_MAIN_001_PIPE_INPUT);
  assertRecursivelyFrozen(MANIFEST_CUR_01_MAIN_001_PIPE_GRAPH);
  assertRecursivelyFrozen(S0_CUR_01_POSITIVE_ORACLE);
  assert.equal(
    MANIFEST_CUR_01_MAIN_001_PIPE_GRAPH.releaseBindings.filter(
      ({ bindingId }) => bindingId === "binding:source",
    ).length,
    1,
  );
  assert.equal(
    MANIFEST_CUR_01_MAIN_001_PIPE_GRAPH.sourceVersionWindows.filter(
      ({ bindingId }) => bindingId === "binding:source",
    ).length,
    1,
  );
  assert.equal(
    S0_CUR_01_NEGATIVE_GRAPH.releaseBindings.some(
      ({ bindingId }) => bindingId === "binding:source",
    ),
    false,
  );
  assert.equal(
    S0_CUR_01_NEGATIVE_GRAPH.sourceVersionWindows.some(
      ({ bindingId }) => bindingId === "binding:source",
    ),
    false,
  );
  assert.deepStrictEqual(
    __testOnlyEvaluateGovernedHouseholdSafetyScenario(
      S0_CUR_01_NEGATIVE_INPUT,
      S0_CUR_01_NEGATIVE_GRAPH,
    ),
    S0_CUR_01_NEGATIVE_ORACLE,
  );
  assert.deepStrictEqual(
    __testOnlyEvaluateGovernedHouseholdSafetyScenario(
      MANIFEST_CUR_01_MAIN_001_PIPE_INPUT,
      MANIFEST_CUR_01_MAIN_001_PIPE_GRAPH,
    ),
    S0_CUR_01_POSITIVE_ORACLE,
  );
});
