test("K-09a", () => {
  assertCONTRACT_K_09AConstructible();
  assertRecursivelyFrozen(S0_K_09A_NEGATIVE_SCENARIO);
  assertRecursivelyFrozen(S0_K_09A_NEGATIVE_ANALYZE_ORACLE);
  assertRecursivelyFrozen(S0_K_09A_POSITIVE_SCENARIO);
  assertRecursivelyFrozen(S0_K_09A_POSITIVE_ANALYZE_ORACLE);
  assertRecursivelyFrozen(S0_K_09A_POSITIVE_KERNEL_ORACLE);
  assert.deepStrictEqual(
    __testOnlyAnalyzeSyntheticHouseholdSafety(S0_K_09A_NEGATIVE_SCENARIO),
    S0_K_09A_NEGATIVE_ANALYZE_ORACLE,
  );
  const positiveAnalyze = __testOnlyAnalyzeSyntheticHouseholdSafety(
    S0_K_09A_POSITIVE_SCENARIO,
  );
  assert.deepStrictEqual(
    projectManifestAnalyzedSuccess(positiveAnalyze),
    S0_K_09A_POSITIVE_ANALYZE_ORACLE,
  );
  if (!positiveAnalyze.ok) {
    assert.fail("K-09a positive ANALYZE must yield a branded state");
  }
  const brandedState = positiveAnalyze.state;
  assert.deepStrictEqual(
    __testOnlyEvaluateAnalyzedHouseholdSafety(brandedState),
    S0_K_09A_POSITIVE_KERNEL_ORACLE,
  );
});
