test("DIG-01", () => {
  assertCONTRACT_DIG_01Constructible();
  const tags = [
    S0_DIG_01_DISH_INPUT.tag,
    S0_DIG_01_REQUEST_INPUT.tag,
    S0_DIG_01_OFFICIAL_PACK_INPUT.tag,
    S0_DIG_01_MAPPING_REVIEW_INPUT.tag,
    S0_DIG_01_SYNTHETIC_GRAPH_INPUT.tag,
    S0_DIG_01_ANALYZED_REQUEST_INPUT.tag,
    S0_DIG_01_ANALYZED_SOURCE_INPUT.tag,
    S0_DIG_01_EVALUATION_INPUT.tag,
  ];
  assert.equal(new Set(tags).size, 8);
  assert.equal(
    tags.every((tag) => /^[\x20-\x7e]+$/u.test(tag) && !tag.includes("\0")),
    true,
  );
  assert.deepStrictEqual(S0_DIG_01_DISH_CALLBACK(), S0_DIG_01_DISH_ORACLE);
  assert.deepStrictEqual(S0_DIG_01_REQUEST_CALLBACK(), S0_DIG_01_REQUEST_ORACLE);
  assert.deepStrictEqual(
    S0_DIG_01_OFFICIAL_PACK_CALLBACK(),
    S0_DIG_01_OFFICIAL_PACK_ORACLE,
  );
  assert.deepStrictEqual(
    S0_DIG_01_MAPPING_REVIEW_CALLBACK(),
    S0_DIG_01_MAPPING_REVIEW_ORACLE,
  );
  assert.deepStrictEqual(
    S0_DIG_01_SYNTHETIC_GRAPH_CALLBACK(),
    S0_DIG_01_SYNTHETIC_GRAPH_ORACLE,
  );
  assert.deepStrictEqual(
    S0_DIG_01_ANALYZED_REQUEST_CALLBACK(),
    S0_DIG_01_ANALYZED_REQUEST_ORACLE,
  );
  assert.deepStrictEqual(
    S0_DIG_01_ANALYZED_SOURCE_CALLBACK(),
    S0_DIG_01_ANALYZED_SOURCE_ORACLE,
  );
  assert.deepStrictEqual(
    S0_DIG_01_EVALUATION_CALLBACK(),
    S0_DIG_01_EVALUATION_ORACLE,
  );
});
